{"cards": [{"node_code": "N_b4f9cb4b6d7f81b8", "definition": "针对船舶动力装置及辅机在运行期间的技术管理，涵盖日常运转操作规范、设备状态监测、故障诊断与排除，以及运行维护策略。", "boundary": "本节点聚焦于“运行中”的管理与维护。边界在于区分“设计制造”（归入船舶工程）与“纯操作技巧”（若侧重驾驶台对机器的操控指令，可关联轮机员，但设备本身维护归此）。若内容涉及主机结构改进或新机型研发，排除；若涉及轮机员个人资质或心理，归入轮机员和驾驶员。", "includes": ["船舶动力装置及辅机的日常运转操作与监控", "设备故障的现场检验、诊断、处理及维修策略", "轮机设备的维护保养计划与运行状态评估"], "excludes": ["船舶主机、辅机的结构设计与制造工艺", "轮机员的适任证书、培训及心理行为研究"], "sibling_distinctions": [{"other_code": "N_c8863bd2424cc0f8", "rule": "本节点关注“设备”的管理与维护（物），兄弟节点关注“人员”的资质、职责与行为（人）。"}, {"other_code": "N_b5973960af0fa3c4", "rule": "本节点涵盖广义的设备运行管理，兄弟节点专门聚焦于“燃料消耗”与“节能”这一特定技术维度。"}], "cross_boundary_rule": "若内容涉及通过优化操作降低油耗，主挂载燃料的消耗与节能技术；若涉及因故障导致的油耗异常排查，主挂载本节点。"}, {"node_code": "N_164f12770ea979ec", "definition": "针对沉没或搁浅船舶及水下障碍物的工程作业，包括沉船勘测、打捞方案设计、实施技术，以及专用潜水器具与仪具的应用。", "boundary": "本节点侧重于“工程实施”与“技术装备”。边界在于区分“救助组织”（侧重指挥、协调、法律与人员搜救，归入海难救助作业与组织）与“打捞工程”（侧重物理打捞、水下作业技术）。若内容涉及沉船污染清理的环境法规，需视具体侧重，若为工程措施则归此。", "includes": ["沉船及水下障碍物的勘测、定位与评估技术", "沉船打捞、起浮、清除的工程方案与实施技术", "救助打捞专用的潜水器具、仪具及水下作业装备"], "excludes": ["海难事故的指挥调度、国际公约及救助合同管理", "常规船舶航行中的潜水娱乐或非工程性水下活动"], "sibling_distinctions": [{"other_code": "N_b6641a855b84189c", "rule": "本节点关注“工程与技术”（如何打捞、用什么工具），兄弟节点关注“组织与管理”（如何指挥、协调资源、法律程序）。"}], "cross_boundary_rule": "若内容涉及救助行动中的具体打捞工程措施，主挂载本节点；若涉及整个救助行动的指挥体系与协调，主挂载海难救助作业与组织。"}, {"node_code": "N_f5ba93e648266c77", "definition": "研究船员在特殊航海环境下的生理、心理变化及健康保障，涵盖航海职业病防治、急救医学、营养卫生及心理健康管理。", "boundary": "本节点聚焦于“人”的健康与医学保障。边界在于区分“一般医学”（非航海特定环境）与“航海医学”（针对封闭、高压、孤立等特定环境）。若内容涉及船员日常行政管理，归入轮机员和驾驶员或相关管理节点；若涉及船舶卫生设施设计，归入船舶工程。", "includes": ["航海环境对船员生理、心理的影响及适应机制", "航海职业病的预防、诊断与治疗", "船上急救医学、卫生防疫及船员营养与心理健康"], "excludes": ["船员的人事管理、薪酬福利及培训考核", "船舶卫生设施的结构设计与建造工艺"], "sibling_distinctions": [{"other_code": "N_c8863bd2424cc0f8", "rule": "本节点关注“健康与医学”（生理/心理状态），兄弟节点关注“职业资质与操作行为”（技能/职责）。"}], "cross_boundary_rule": "若内容涉及船员因疾病无法履职的医学鉴定，主挂载本节点；若涉及船员因技能不足导致的操作失误，主挂载轮机员和驾驶员。"}]}
